function bindUsers(){let doc=root.document,$=id=>doc.getElementById(id);if($('accessReload'))$('accessReload').onclick=()=>{if(saving)return;if(changed&&!root.confirm('Descartar as alterações de permissão ainda não salvas?'))return;users=null;changed=false;loadUsers()};if($('accessUser'))$('accessUser').onchange=()=>{if(saving)return;if(changed&&!root.confirm('Descartar as alterações de permissão ainda não salvas?')){$('accessUser').value=selected;return}choose($('accessUser').value);bridge.render()};for(let el of doc.querySelectorAll('[data-access-module]'))el.onchange=()=>{draft.modules=draft.modules||{};draft.views=draft.views||{};let key=el.dataset.accessModule;draft.modules[key]=el.value;for(let v of catalog.find(m=>m.key===key).views)draft.views[v.key]=el.value;changed=true;bridge.render()};for(let el of doc.querySelectorAll('[data-access-view]'))el.onchange=()=>{let key=el.dataset.accessView,mod=moduleFor(key),cap=draft.modules?.[mod.key]||'none';if(levels[el.value]>levels[cap]){bridge.toast('Primeiro amplie a permissão do módulo para permitir este nível.');el.value=draft.views?.[key]||cap;return}draft.views=draft.views||{};draft.views[key]=el.value;changed=true;if($('accessStatus'))$('accessStatus').textContent='Alterações ainda não salvas.'};if($('accessSave'))$('accessSave').onclick=async()=>{if(saving)return;let user=users.find(u=>u.id===selected);try{saving=true;$('accessSave').disabled=true;await root.EngefexCloud.setAccess(user.id,user.revision,clone(draft));changed=false;bridge.toast('Permissões salvas. A sessão do usuário será atualizada automaticamente.');users=null;await loadUsers()}catch(e){if($('accessStatus'))$('accessStatus').textContent=e.message}finally{saving=false;if($('accessSave'))$('accessSave').disabled=false}}}
